### 我的解法

设 \(a,b\) 的 \(k\) 进制第 \(i\) 位分别为 \(a_i,b_i\)，不进位相加后该位为 \(c_i=(a_i+b_i)\bmod k\)。于是
\[
a+b-c=k\sum_i \left\lfloor\frac{a_i+b_i}{k}\right\rfloor k^i.
\]
因此，若 \(d=a+b-c>0\)，合法的 \(k\) 一定是 \(d\) 的因子；再逐位检查 \(a,b,c\) 是否符合定义即可。

- \(d<0\)：不可能，答案为 0。
- \(d=0\)：取足够大的 \(k\)，三个数都可写成一位，且 \(a+b=c\)，所以有无穷多个，输出 -1。
- \(d>0\)：枚举 \(d\) 的因子 \(k\ge2\)，逐位验证。

```cpp
#include <bits/stdc++.h>
using namespace std;

bool valid(long long k, long long a, long long b, long long c) {
    while (a > 0 || b > 0 || c > 0) {
        if ((a % k + b % k) % k != c % k) return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;

        long long d = a + b - c;
        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int answer = 0;
            for (long long i = 1; i * i <= d; ++i) {
                if (d % i != 0) continue;

                long long j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++answer;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++answer;
            }
            cout << answer << '\n';
        }
    }
    return 0;
}
